            counts[node[1]]+=counts[i]; counts[node[2]]+=counts[i]
    assert all(c<=budgets[k] for k,c in phys.items()), (phys,budgets)

def run(seed, Nmax=10):
    random.seed(seed)
    n=random.randint(2,Nmax)
    links=[(u,v) for u in range(n) for v in range(u+1,n) if random.random()<random.random()]
    env=[[l,random.randint(1,12)] for l in range(len(links)) if random.random()<0.95]
    C=random.sample(range(n), random.randint(2,min(n,8)))
    parts=[[v,random.randint(0,10)] for v in C]
    if not sum(r for v,r in parts): parts[0][1]=1
    period=random.randint(1,5)
    try:
        plan, cut=compile_plan(n, links, parts, env, period)
        check(n,links,parts,env,period,plan,cut)
    except BaseException:
        print('FAIL',seed, n,links,parts,env,period,flush=True)
        raise
    return cut is None

if __name__=='__main__':
