"""Persistent lease book and protocol validation (integer-only)."""
import re
from compiler import compile_plan

MAX = 10**12
NAME = re.compile(r'[A-Za-z0-9_.-]{1,32}\Z', re.ASCII)


def integer(x, lo=0, hi=MAX):
    return type(x) is int and lo <= x <= hi


def name(x):
    return type(x) is str and NAME.fullmatch(x) is not None


def fields(x, keys):
    return type(x) is dict and x.keys() == keys


def window(x):
    return (type(x) is list and len(x) == 2 and integer(x[0]) and
            integer(x[1]) and x[0] < x[1])


def pairs(x, limit, keymax, valuemin=0):
    if type(x) is not list or len(x) > limit:
        return False
    seen = set()
    for a in x:
        if (type(a) is not list or len(a) != 2 or
                not integer(a[0], 0, keymax) or not integer(a[1], valuemin) or a[0] in seen):
            return False
        seen.add(a[0])
    return True


def booking(x):
    return (fields(x, {'id', 'owner', 'window', 'envelope'}) and name(x['id']) and
            name(x['owner']) and window(x['window']) and pairs(x['envelope'], 128, 127, 1))


def valid(x):
    if type(x) is not dict or type(x.get('op')) is not str:
        return False
    op = x['op']
    if op == 'about':
        return fields(x, {'op'})
    if op == 'load':
        if not fields(x, {'op', 'n', 'links', 'bookings'}) or not integer(x['n'], 2, 48):
            return False
        links, bs = x['links'], x['bookings']
        if type(links) is not list or len(links) > 128 or type(bs) is not list or len(bs) > 128:
            return False
        seen = set()
        for link in links:
            if (type(link) is not list or len(link) != 3 or not integer(link[0], 0, x['n']-1)
                    or not integer(link[1], 0, x['n']-1) or link[0] == link[1] or not integer(link[2])):
                return False
            key = tuple(sorted(link[:2]))
            if key in seen:
                return False
            seen.add(key)
        seen = set()
        entries = 0
        for b in bs:
            if not booking(b) or b['id'] in seen:
                return False
            if any(l >= len(links) for l, _ in b['envelope']):
                return False
            entries += len(b['envelope'])
            seen.add(b['id'])
        return entries <= 2048
    if op == 'audit':
        return (fields(x, {'op', 'at'}) and type(x['at']) is list and len(x['at']) <= 8
                and all(integer(t) for t in x['at']))
    if op == 'advance':
        return fields(x, {'op', 'time'}) and integer(x['time'])
    if op == 'edit':
        return (fields(x, {'op', 'rev', 'changes', 'force'}) and integer(x['rev']) and
                pairs(x['changes'], 128, 127) and type(x['force']) is bool)
    if op == 'prepare':
        return (fields(x, {'op', 'id', 'owner', 'window', 'period', 'participants', 'envelope', 'rev'})
                and name(x['id']) and name(x['owner']) and window(x['window'])
                and integer(x['period'], 1, 10**6) and integer(x['rev'])
                and pairs(x['participants'], 32, 47) and len(x['participants']) >= 2
                and sum(r for _, r in x['participants']) > 0
                and pairs(x['envelope'], 128, 127, 1))
    if op in ('commit', 'cancel'):
        return (fields(x, {'op', 'id', 'owner', 'rev'}) and name(x['id']) and
                name(x['owner']) and integer(x['rev']))
    return False


class Controller:
    def __init__(self):
        self.loaded = False
        self.rev = self.now = 0
        self.history = {}
        self.live = {}

    def error(self, code):
        return {'status': 'error', 'code': code, 'rev': self.rev}

    def stale(self):
        return {'status': 'stale', 'rev': self.rev}

    def used(self, at):
        out = [0] * len(self.links)
        for b in self.live.values():
            if b['window'][0] <= at < b['window'][1]:
                for l, r in b['envelope']:
                    out[l] += r
        return out

    def overbook(self, capacities, start, end, offered=()):
        """Return a valid integral overload witness in [start,end)."""
        usage = [0] * len(capacities)
        for l, r in offered:
            usage[l] += r
        events = {}
        for b in self.live.values():
            s, e = b['window']
            if e <= start or s >= end:
                continue
            if s <= start:
                for l, r in b['envelope']:
                    usage[l] += r
            else:
                events.setdefault(s, []).append((b['envelope'], 1))
            # An active booking must stop contributing at its end.  Endpoints
            # are half-open, so checking after this event is checking the next
            # tick and is sufficient.
            if e < end:
                events.setdefault(e, []).append((b['envelope'], -1))
        def bad(t):
            for l, u in enumerate(usage):
                if u > capacities[l]:
                    return l, t, u, capacities[l]
            return None
        hit = bad(start)
        if hit:
            return hit
        for t in sorted(events):
            for env, sign in events[t]:
                for l, r in env:
                    usage[l] += sign * r
            hit = bad(t)
            if hit:
                return hit
        return None

    def handle(self, x):
        if not valid(x):
            return {'status': 'invalid'}
        op = x['op']
        if op == 'about':
            return {'status': 'ok', 'protocol': 'forest-controller/3'}
        if op == 'load':
            if self.loaded:
                return self.error('ALREADY_LOADED')
            # Validate overlaps in temporary state, without installing a failed load.
            caps = [a[2] for a in x['links']]
            staged = Controller()
            staged.live = {b['id']: b for b in x['bookings']}
            if staged.overbook(caps, 0, MAX+1):
                return {'status': 'invalid'}
            self.n = x['n']
            self.links = [tuple(a[:2]) for a in x['links']]
            self.live = staged.live
            self.capacities = caps
            self.history = {b['id']: {'owner': b['owner'], 'state': 'live'} for b in x['bookings']}
            self.loaded = True
            return {'status': 'ok', 'rev': 0, 'now': 0}
        if not self.loaded:
            return self.error('NOT_LOADED')
        if op == 'audit':
            if any(t < self.now for t in x['at']):
                return self.error('TIME')
            samples = [[t, [c-u for c, u in zip(self.capacities, self.used(t))]] for t in x['at']]
            return {'status': 'ok', 'rev': self.rev, 'now': self.now,
                    'leases': sorted(self.live), 'samples': samples}
        if op == 'advance':
            t = x['time']
            if t < self.now:
                return self.error('TIME')
            expired = sorted(k for k, b in self.live.items() if b['window'][1] <= t)
            for k in expired:
                del self.live[k]
                self.history[k]['state'] = 'dead'
            self.now = t
            self.rev += 1
            return {'status': 'ok', 'rev': self.rev, 'now': t, 'expired': expired}
        if op == 'edit':
            if x['rev'] != self.rev:
                return self.stale()
            if any(l >= len(self.links) for l, _ in x['changes']):
                return self.error('REFERENCE')
            caps = self.capacities[:]
            for l, c in x['changes']:
                caps[l] = c
            cancelled = []
            if x['force']:
                decreased = {l for l, c in x['changes'] if c < self.capacities[l]}
                cancelled = sorted(k for k, b in self.live.items()
                                   if any(l in decreased for l, _ in b['envelope']))
            else:
                bad = self.overbook(caps, self.now, MAX+1)
                if bad:
                    l, t, u, c = bad
                    return {'status': 'blocked', 'rev': self.rev, 'link': l, 'time': t,
                            'used': u, 'capacity': c}
            for k in cancelled:
                del self.live[k]
                self.history[k]['state'] = 'dead'
            self.capacities = caps
            self.rev += 1
            return {'status': 'ok', 'rev': self.rev, 'cancelled': cancelled}
        if op == 'prepare':
            key = x['id']
            identity = (x['owner'], tuple(x['window']), x['period'], x['rev'],
                        tuple(sorted(map(tuple, x['participants']))), tuple(sorted(map(tuple, x['envelope']))))
            if key in self.history:
                h = self.history[key]
                if h.get('identity') != identity:
                    return self.error('CONFLICT')
                return {'status': 'replay', 'id': key, 'rev': self.rev,
                        'base_rev': h['base_rev'], 'outcome': h['outcome']}
            if x['rev'] != self.rev:
                return self.stale()
            if (any(v >= self.n for v, _ in x['participants']) or
                    any(l >= len(self.links) for l, _ in x['envelope'])):
                return self.error('REFERENCE')
            s, e = x['window']
            if s < self.now:
                return self.error('TIME')
            if (e-s) % x['period']:
                return self.error('WINDOW')
            bad = self.overbook(self.capacities, s, e, x['envelope'])
            if bad:
                l, t, u, c = bad
                result = {'status': 'denied', 'id': key, 'rev': self.rev, 'kind': 'capacity',
                          'link': l, 'time': t, 'used': u, 'capacity': c}
            else:
                plan, cut = compile_plan(self.n, self.links, x['participants'], x['envelope'], x['period'])
                if cut is not None:
                    result = {'status': 'denied', 'id': key, 'rev': self.rev, 'kind': 'cut', 'cut': cut}
                else:
                    result = {'status': 'prepared', 'id': key, 'rev': self.rev, 'plan': plan}
            outcome = 'prepared' if result['status'] == 'prepared' else 'denied'
            self.history[key] = {'owner': x['owner'], 'identity': identity, 'base_rev': self.rev,
                                 'outcome': outcome, 'state': outcome, 'booking': x}
            return result
        if op == 'commit':
            key = x['id']
            h = self.history.get(key)
            if h is None:
                return self.error('MISSING')
            if x['owner'] != h['owner']:
                return self.error('OWNER')
            if h['state'] == 'live':
                return {'status': 'ok', 'id': key, 'rev': self.rev, 'replay': True}
            if h['state'] == 'dead':
                return self.error('GONE')
            if h['state'] == 'denied':
                return self.error('DENIED')
            if x['rev'] != self.rev or h['base_rev'] != self.rev:
                return self.stale()
            h['state'] = 'live'
            self.live[key] = h['booking']
            self.rev += 1
            return {'status': 'ok', 'id': key, 'rev': self.rev, 'replay': False}
        if op == 'cancel':
            if x['rev'] != self.rev:
                return self.stale()
            key = x['id']
            if key not in self.live:
                return self.error('MISSING')
            if x['owner'] != self.history[key]['owner']:
                return self.error('OWNER')
            del self.live[key]
            self.history[key]['state'] = 'dead'
            self.rev += 1
            return {'status': 'ok', 'rev': self.rev, 'released': key}

controller = Controller()


def handle(request):
    return controller.handle(request)
"""Exact integral splitting-off and weighted branching packing.

The super-source has r[v] units to v.  Admission is equivalent to a D-flow
from that source to each receiver.  Complete directed splitting-off removes
non-compute vertices while maintaining those cuts.  The resulting compute
multigraph is decomposed into weighted out-branchings; path pools retain the
serial, rather than multicast, meaning of each split.
"""
from collections import deque


class Network:
    """A mutable capacitated graph with an exact, bounded Dinic oracle.

    Opposite original arcs share a residual pair; this is also valid when both
    original directions have nonzero capacity. Temporary forced arcs do not
    change the underlying network.
    """
    def __init__(self, n):
        self.n = n
        self.adj = [[] for _ in range(n)]
        self.to = []
        self.cap = []
        self.index = [{} for _ in range(n)]
        self.calls = 0

    def node(self):
        k = self.n
        self.n += 1
        self.adj.append([])
        self.index.append({})
        return k

    def edge(self, u, v):
        if v in self.index[u]:
            return self.index[u][v]
        i = len(self.cap)
        self.index[u][v] = i
        self.index[v][u] = i+1
        self.to.extend((v, u))
        self.cap.extend((0, 0))
        self.adj[u].append(i)
        self.adj[v].append(i+1)
        return i

    def add(self, u, v, c):
        self.cap[self.edge(u, v)] += c

    def get(self, u, v):
        i = self.index[u].get(v)
        return self.cap[i] if i is not None else 0

    def flow(self, s, t, limit, forced=(), want_cut=False):
        self.calls += 1
        adj, to = self.adj, self.to
        cap = self.cap[:]
        temporary = []
        for u, v, c in forced:
            i = self.index[u].get(v)
            if i is None:
                i = len(to)
                to.extend((v, u))
                cap.extend((c, 0))
                adj[u].append(i)
                adj[v].append(i+1)
                temporary.append((u, v))
            else:
                cap[i] = c
        n = self.n
        total = 0
        levels = None
        while total < limit:
            level = [-1]*n
            level[s] = 0
            q = [s]
            for u in q:
                if level[t] >= 0 and level[u] >= level[t]:
                    break
                lu = level[u]+1
                for i in adj[u]:
                    v = to[i]
                    if cap[i] > 0 and level[v] < 0:
                        level[v] = lu
                        q.append(v)
            if level[t] < 0:
                levels = level
                break
            pos = [0]*n
            sizes = [len(a) for a in adj]

            def send(u, amount):
                if u == t:
                    return amount
                aa = adj[u]
                j = pos[u]
                next_level = level[u]+1
                while j < sizes[u]:
                    i = aa[j]
                    v = to[i]
                    ci = cap[i]
                    if ci and level[v] == next_level:
                        z = send(v, amount if amount < ci else ci)
                        if z:
                            cap[i] -= z
                            cap[i ^ 1] += z
                            pos[u] = j
                            return z
                    j += 1
                pos[u] = j
                level[u] = -1
                return 0

            while total < limit:
                z = send(s, limit-total)
                if not z:
                    break
                total += z
        for u, v in reversed(temporary):
            adj[u].pop()
            adj[v].pop()
            to.pop()
            to.pop()
        if want_cut:
            if total == limit:
                return total, None
            if levels is None:
                seen = {s}
                q = [s]
                for u in q:
                    for i in adj[u]:
                        if cap[i] and to[i] not in seen:
                            seen.add(to[i])
                            q.append(to[i])
            else:
                seen = {u for u, lev in enumerate(levels) if lev >= 0}
            return total, seen
        return total


class Pools:
    def __init__(self, links, rates):
        self.recipes = []
        self.pools = {}
        for l, (u, v) in enumerate(links):
            c = rates[l]
            if c:
                for direction, a, b in ((0, u, v), (1, v, u)):
                    k = len(self.recipes)
                    self.recipes.append([0, l, direction])
                    self.pools[a, b] = deque([[k, c]])

    def split(self, u, w, v, amount):
        a, b = self.pools[u, w], self.pools[w, v]
        out = self.pools.setdefault((u, v), deque()) if u != v else None
        while amount:
            x, cx = a[0]
            y, cy = b[0]
            z = min(cx, cy, amount)
            if out is not None:
                k = len(self.recipes)
                self.recipes.append([1, x, y])
                out.append([k, z])
            a[0][1] -= z
            b[0][1] -= z
            if not a[0][1]:
                a.popleft()
            if not b[0][1]:
                b.popleft()
            amount -= z

    def routes(self, loads):
        routes = []
        for (u, v), amount in sorted(loads.items()):
            pool = self.pools[u, v]
            while amount:
                k, c = pool[0]
                z = min(c, amount)
                routes.append([u, v, z, k])
                amount -= z
                pool[0][1] -= z
                if not pool[0][1]:
                    pool.popleft()
        # Only the reachable circuit is published, in topological order.
        used = set()
        stack = [r[3] for r in routes]
        while stack:
            k = stack.pop()
            if k in used:
                continue
            used.add(k)
            node = self.recipes[k]
            if node[0] == 1:
                stack.extend(node[1:])
        ids = {old: i for i, old in enumerate(sorted(used))}
        recipes = []
        for old in sorted(used):
            node = self.recipes[old]
            if node[0] == 1:
                recipes.append([1, ids[node[1]], ids[node[2]]])
            else:
                recipes.append(node)
        for r in routes:
            r[3] = ids[r[3]]
        return routes, recipes


def eliminate(net, n, terminals, demand, pools):
    source = n
    D = sum(demand.values())
    # More than the capacity of any constrained cut of interest.
    inf = sum(net.cap)+D+1
    alive = set(range(n))
    # Low degree first keeps both the circuit and the flow problems small.
    ordinary = set(range(n))-set(terminals)
    while ordinary:
        w = min(ordinary, key=lambda x: sum(net.get(x, v) > 0 or net.get(v, x) > 0 for v in alive if x != v))
        ordinary.remove(w)
        neighbors = sorted(alive-{w})
        for u in neighbors:
            if not net.get(u, w):
                continue
            for v in neighbors:
                amount = min(net.get(u, w), net.get(w, v))
                if not amount:
                    continue
                # Only two types of cut lose capacity: w inside, u/v
                # outside, or vice versa. First try an unconstrained cut. If
                # its sink side contains a receiver it is already the exact
                # minimum; otherwise constrain one receiver at a time.
                common = [(u, source, inf)]
                if u != v:
                    common.append((u, v, inf))
                f, reachable = net.flow(u, w, D+amount, common, want_cut=True)
                if f < D+amount:
                    if any(t not in reachable for t in terminals):
                        amount = min(amount, f-D)
                    else:
                        for t in terminals:
                            if t == u or t == v:
                                continue
                            f = net.flow(u, w, D+amount, common+[(t, w, inf)])
                            amount = min(amount, f-D)
                            if not amount:
                                break
                if amount:
                    common = [(w, source, inf)]
                    if u != v:
                        common.append((u, v, inf))
                    f, reachable = net.flow(w, v, D+amount, common, want_cut=True)
                    if f < D+amount:
                        if any(t not in reachable for t in terminals):
                            amount = min(amount, f-D)
                        else:
                            for t in terminals:
                                f = net.flow(w, v, D+amount, common+[(t, v, inf)])
                                amount = min(amount, f-D)
                                if not amount:
                                    break
                assert amount >= 0
                if amount:
                    net.add(u, w, -amount)
                    net.add(w, v, -amount)
                    if u != v:
                        net.add(u, v, amount)
                    pools.split(u, w, v, amount)
                if not net.get(u, w):
                    break
            assert not net.get(u, w), ('incomplete split', u, w, net.get(u, w))
        assert all(not net.get(w, v) and not net.get(v, w) for v in alive if v != w)
        alive.remove(w)
        cleaned = Network(net.n)
        for i in range(0, len(net.cap), 2):
            if net.cap[i] or net.cap[i+1]:
                a, b = net.to[i+1], net.to[i]
                cleaned.add(a, b, net.cap[i])
                cleaned.add(b, a, net.cap[i+1])
        net.adj, net.index = cleaned.adj, cleaned.index
        net.to, net.cap = cleaned.to, cleaned.cap


def branchings(net, vertices, demands):
    """Weighted version of the legacy branching generator.

    An unfinished tree is represented by its reached set and multiplicity.
    A min-cut gives the largest integral weight of an admissible extension.
    Identical reached sets share an auxiliary node.
    """
    vertices = sorted(vertices)
    N = len(vertices)
    # A fresh graph avoids all dead splitting vertices and stale residual arcs.
    g = Network(N)
    idx = {u: i for i, u in enumerate(vertices)}
    for u in vertices:
        for v in vertices:
            if u != v and net.get(u, v):
                g.add(idx[u], idx[v], net.get(u, v))
    total = sum(demands.values())
    inf = sum(g.cap)+total+1
    # Each group holds a root, edge prefix, reached bitset and count.
    pending = deque()
    groups = {}  # reached set -> total weight (other trees of that shape)
    full = (1 << N)-1

    def change(mask, amount):
        groups[mask] = groups.get(mask, 0)+amount
        if not groups[mask]:
            del groups[mask]

    def admissible(x, y, amount):
        # A group already containing y crosses every x-y cut, and adds the
        # same constant to the oracle value and the required baseline. Omit it.
        other = sum(c for m, c in groups.items() if not m >> y & 1)
        if not other:
            return amount
        h = Network.__new__(Network)
        h.n = N
        h.adj = [a[:] for a in g.adj]
        h.index = [a.copy() for a in g.index]
        h.to = g.to[:]
        h.cap = g.cap[:]
        h.calls = 0
        for m, c in groups.items():
            if m >> y & 1:
                continue
            if not m & (m-1):
                v = m.bit_length()-1
                if v != x:
                    h.add(x, v, c)
            else:
                a = h.node()
                h.add(x, a, c)
                for v in range(N):
                    if m >> v & 1:
                        h.add(a, v, inf)
        f = h.flow(x, y, other+amount)
        return min(amount, f-other)

    for root in vertices:
        if demands[root]:
            mask = 1 << idx[root]
            pending.append((root, [], mask, demands[root]))
            change(mask, demands[root])
    trees = []
    loads = {}
    while pending:
        root, edges, mask, count = pending.popleft()
        change(mask, -count)
        # Growing the selected fragment: its own auxiliary source is omitted.
        queue = [i for i in range(N) if mask >> i & 1]
        for x in queue:
            for y in range(N):
                if mask >> y & 1 or not g.get(x, y):
                    continue
                amount = min(count, g.get(x, y))
                amount = admissible(x, y, amount)
                if amount <= 0:
                    continue
                if amount < count:
                    pending.append((root, edges[:], mask, count-amount))
                    change(mask, count-amount)
                    count = amount
                edges.append([vertices[x], vertices[y]])
                mask |= 1 << y
                queue.append(y)
                g.add(x, y, -count)
                if mask == full:
                    break
            if mask == full:
                break
        assert mask == full, ('incomplete branching', root, count, mask, full)
        trees.append([root, count, edges])
        for u, v in edges:
            loads[u, v] = loads.get((u, v), 0)+count
    assert len(trees) <= 8192
    return trees, loads


def compile_plan(n, links, participants, envelope, period):
    demands = dict(participants)
    terminals = sorted(demands)
    D = sum(demands.values())
    rates = [0]*len(links)
    for l, b in envelope:
        # No terminal-separating cut requires more than D. Clipping each
        # link to D preserves all admission cuts and reduces needless surplus.
        rates[l] = min(b*period, D)
    net = Network(n+1)
    for l, (u, v) in enumerate(links):
        c = rates[l]
        if c:
            net.add(u, v, c)
            net.add(v, u, c)
    for v, r in participants:
        net.add(n, v, r)
    for v in terminals:
        f, reachable = net.flow(n, v, D, want_cut=True)
        if f < D:
            return None, sorted(reachable-{n})
    pools = Pools(links, rates)
    eliminate(net, n, terminals, demands, pools)
    trees, loads = branchings(net, terminals, demands)
    routes, recipes = pools.routes(loads)
    assert len(routes) <= 32768 and len(recipes) <= 65536
    return {'trees': trees, 'routes': routes, 'recipes': recipes}, None
